ctx13='600 employee names in collectionNAMES, formatted surname, first name; split then bubble-sort parallel arrays and binary-search surnames.'
split='def split_names(entries):\n    surnames = []\n    firstnames = []\n    for entry in entries:\n        surname, first = entry.split(",", 1)\n        surnames.append(surname.strip())\n        firstnames.append(first.strip())\n    return surnames, firstnames'
add(13,'a',6,4,'Construct','Construct a pseudocode algorithm that will store the surnames in one array and first names in another.',ctx13,[10],'Loopcollection,split/extractfields,correctparallelassignments; source ambiguous collection representation.','B',['B2.1.2','B2.2.2'],'Replace old collection API with explicitly formatted Python strings.','Construct Python function split_names(entries) returning two parallel lists of surnames and firstnames. Each input string has exactly one comma separating surname from firstnames; strip surrounding spaces. For example "Okafor, Ada".',''+split,'Creates two result lists.|Traverses all entries.|Splits correctly at comma and strips spaces.|Appends matching surname/firstname at same index and returns both.',code=split,test='Executed on empty input,spaces and multiple firstnames; expectedparallel lists verified.')
bubble='def sort_names(surnames, firstnames):\n    n = len(surnames)\n    for end in range(n - 1, 0, -1):\n        for i in range(end):\n            if surnames[i] > surnames[i + 1]:\n                surnames[i], surnames[i + 1] = surnames[i + 1], surnames[i]\n                firstnames[i], firstnames[i + 1] = firstnames[i + 1], firstnames[i]'
