validate='def summarize(read_value):\n    count = 0\n    total = 0\n    low = high = None\n    while count < 5:\n        value = read_value()\n        if type(value) is int and 0 <= value <= 1000:\n            if count == 0:\n                low = high = value\n            if value < low:\n                low = value\n            if value > high:\n                high = value\n            total += value\n            count += 1\n    return low, high, total / count'
